mapper.select:
select a.id, a.api_code, a.rule_number as ruleNumber, a.rule_name as ruleName, a.dependency_template_id as dependencyTemplateId, b.name as dependencyTemplateName, b.source_type as dependencyTemplateSource, a.status as status, a.auto_time as autoTime, a.push_datasets as pushDatasets, a.auto_refresh as autoRefresh, a.reach_strategy as reachStrategy, a.push_target as pushTarget, date_format(a.create_time,'%Y-%m-%d %T') as createTime, date_format(a.update_time,'%Y-%m-%d %T') as updateTime from b_marketing_push_decisions a left join b_score_search_condition as b on a.dependency_template_id = b.id where a.is_del = 1 and b.is_del = 1
and a.api_code = #{apiCode}
and a.rule_name = #{name}
and a.status = #{status}
order by a.update_time desc
